  \coordinate (vD) at (0.0,0.0);
  \draw[ink,fill=brand!8] (vA) -- (vB) -- (vC) -- (vD) -- cycle;
  \node[above left] at (vA) {$A$};
  \node[above right] at (vB) {$B$};
  \node[below right] at (vC) {$C$};
  \node[below left] at (vD) {$D$};
  \node[brand,font=\scriptsize] at (3.48,0.72) {$80^\circ$};
  \node[brand,font=\scriptsize] at (0.44,0.3) {$70^\circ$};
  \draw[brand,line width=1.0pt] (vA) -- (1.72,1.06);
  \draw[brand,line width=1.0pt] (vB) -- (1.72,1.06);
  \fill[brand] (1.72,1.06) circle (1.3pt) node[below=1pt,ink]{$I$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Ví dụ 2}
\end{minipage}

\par\nopagebreak
\begin{minipage}[t]{0.62\linewidth}\vspace{0pt}
\textbf{Ví dụ 3.} Cho tứ giác $ABCD$ có $AB=AD$, $CB=CD$. [[br]] a) Chứng minh $AC$ là đường trung trực của đoạn thẳng $BD$. [[br]] b) Biết $\widehat{C}=60^\circ$, $\widehat{A}=100^\circ$. Tính $\widehat{B}$ và $\widehat{D}$.[[br]]{\sffamily\bfseries\color{brand}Lời giải}[[br]]\textbf{a)} Vì $AB=AD$ nên điểm $A$ cách đều hai đầu mút của đoạn thẳng $BD$,[[br]]\hspace*{1.4em}do đó $A$ nằm trên đường trung trực của $BD$.[[br]]\hspace*{1.4em}Vì $CB=CD$ nên điểm $C$ cũng nằm trên đường trung trực của $BD$.[[br]]\hspace*{1.4em}Đường trung trực của $BD$ đi qua hai điểm phân biệt $A$ và $C$ nên nó chính là đường thẳng $AC$.[[br]]\hspace*{1.4em}Vậy $AC$ là đường trung trực của đoạn thẳng $BD$.[[br]]\textbf{b)} Xét $\triangle ABC$ và $\triangle ADC$ có: $AB=AD$ (giả thiết), $CB=CD$ (giả thiết), $AC$ là cạnh chung.[[br]]\hspace*{1.4em}Do đó $\triangle ABC = \triangle ADC$ (c.c.c), suy ra $\widehat{B} = \widehat{D}$.[[br]]\hspace*{1.4em}Vì tổng bốn góc của tứ giác bằng $360^\circ$ nên $\widehat{B}+\widehat{D} = 360^\circ - 100^\circ - 60^\circ = 200^\circ$.[[br]]\hspace*{1.4em}Mà $\widehat{B} = \widehat{D}$ nên $\widehat{B} = \widehat{D} = 200^\circ : 2 = 100^\circ$.[[br]]\hspace*{1.4em}Vậy $\widehat{B} = \widehat{D} = 100^\circ$.
\end{minipage}\hfill
